<script setup>
import { computed, ref } from 'vue'
const props = defineProps({ menus: { type: Array, default: () => [] } })
const emit = defineEmits(['create', 'update', 'refresh'])
const dialogOpen = ref(false)
const editingID = ref(0)
const form = ref(emptyMenu())
const expandedMenuKeys = ref({})
const sortedMenus = computed(() => [...props.menus].sort((a,b) => Number(a.sort)-Number(b.sort) || Number(a.ID)-Number(b.ID)))
const rootMenus = computed(() => sortedMenus.value.filter((m) => !m.parent_key))
function emptyMenu() { return { name:'', menu_key:'', parent_key:'', view_key:'', description:'', sort:0, is_enabled:true } }
function childrenOf(menu) { return sortedMenus.value.filter((item) => item.parent_key === menu.menu_key) }
function isExpanded(menu) { return expandedMenuKeys.value[menu.menu_key] === true }
function toggleExpanded(menu) { expandedMenuKeys.value = { ...expandedMenuKeys.value, [menu.menu_key]: !isExpanded(menu) } }
function openCreate() { editingID.value = 0; form.value = emptyMenu(); dialogOpen.value = true }
function edit(menu) { editingID.value = menu.ID; form.value = { name:menu.name||'', menu_key:menu.menu_key||'', parent_key:menu.parent_key||'', view_key:menu.view_key||'', description:menu.description||'', sort:Number(menu.sort)||0, is_enabled:menu.is_enabled !== false }; dialogOpen.value = true }
function closeDialog() { dialogOpen.value = false; editingID.value = 0; form.value = emptyMenu() }
function submit() { const payload = { ...form.value, name:form.value.name.trim(), menu_key:form.value.menu_key.trim(), parent_key:form.value.parent_key.trim(), view_key:form.value.view_key.trim(), description:form.value.description.trim(), sort:Number(form.value.sort)||0 }; emit(editingID.value ? 'update' : 'create', editingID.value ? { id:editingID.value, ...payload } : payload); closeDialog() }
</script>

<template>
  <section class="page-stack"><article class="panel"><header class="panel-heading panel-actions-only"><div class="heading-actions"><button class="primary" type="button" @click="openCreate">＋ 新建菜单</button><button class="text-button" type="button" @click="emit('refresh')">刷新</button></div></header><ul class="menu-list"><template v-for="menuItem in rootMenus" :key="menuItem.ID"><li class="menu-item parent"><div class="menu-summary"><strong>{{ menuItem.name }}</strong><small>{{ menuItem.menu_key }} · {{ menuItem.view_key || '目录菜单' }}</small><small>{{ menuItem.description || '未填写用途说明' }}</small></div><div class="actions"><button v-if="childrenOf(menuItem).length" class="expand-button" type="button" @click="toggleExpanded(menuItem)">{{ isExpanded(menuItem) ? '收起' : '展开' }} {{ childrenOf(menuItem).length }}</button><span :class="['status',{disabled:!menuItem.is_enabled}]">{{ menuItem.is_enabled ? '启用' : '停用' }}</span><button class="text-button" type="button" @click="edit(menuItem)">编辑</button></div></li><li v-for="child in childrenOf(menuItem)" v-show="isExpanded(menuItem)" :key="child.ID" class="menu-item child"><div class="menu-summary"><strong>{{ child.name }}</strong><small>{{ child.menu_key }} · {{ child.view_key || '目录菜单' }}</small><small>{{ child.description || '未填写用途说明' }}</small></div><div class="actions"><span :class="['status',{disabled:!child.is_enabled}]">{{ child.is_enabled ? '启用' : '停用' }}</span><button class="text-button" type="button" @click="edit(child)">编辑</button></div></li></template><li v-if="!props.menus.length" class="muted">菜单尚未同步。</li></ul></article>
    <div v-if="dialogOpen" class="modal-backdrop" @click.self="closeDialog"><section class="modal-card" role="dialog" aria-modal="true" aria-labelledby="menu-dialog-title"><header class="modal-heading"><div><p>FRONTEND NAVIGATION</p><h2 id="menu-dialog-title">{{ editingID ? '编辑菜单' : '新建菜单' }}</h2></div><button class="icon-button" type="button" aria-label="关闭" @click="closeDialog">×</button></header><div class="modal-scroll"><p class="helper">保存后，菜单会参与角色可见性和导航目录计算。</p><form class="form-stack" @submit.prevent="submit"><label>菜单名称<input v-model="form.name" required maxlength="128" placeholder="例如：权限管理" /></label><label>菜单键<input v-model="form.menu_key" required maxlength="128" placeholder="例如：permission_management" /></label><label>父级菜单键<select v-model="form.parent_key"><option value="">无（一级菜单）</option><option v-for="menuItem in props.menus.filter((item) => item.ID !== editingID)" :key="menuItem.ID" :value="menuItem.menu_key">{{ menuItem.name }}（{{ menuItem.menu_key }}）</option></select></label><label>前端视图键<input v-model="form.view_key" maxlength="128" placeholder="页面菜单例如 organizations" /></label><label>用途说明<input v-model="form.description" maxlength="500" placeholder="说明菜单用途" /></label><label>排序<input v-model.number="form.sort" type="number" /></label><label class="switch"><input v-model="form.is_enabled" type="checkbox" /> 在导航中启用</label><footer class="modal-actions"><button class="ghost" type="button" @click="closeDialog">取消</button><button class="primary" type="submit">{{ editingID ? '保存菜单' : '创建菜单' }}</button></footer></form></div></section></div>
  </section>
</template>

<style scoped>
.page-stack{display:grid;gap:20px}.panel{padding:26px;border:1px solid #dce5df;border-radius:12px;background:#fff;box-shadow:0 10px 28px rgba(30,58,44,.05)}.panel-heading,.modal-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.panel-heading{align-items:center;margin-bottom:14px}.panel-heading p,.modal-heading p{margin:0;color:#5c796c;font-size:11px;font-weight:800;letter-spacing:.12em}.panel-heading h2,.modal-heading h2{margin:6px 0 0;color:#173f31;font-size:22px}.heading-actions,.actions,.modal-actions{display:flex;align-items:center;gap:10px}.helper{margin:0 0 18px;color:#65766d;font-size:13px;line-height:1.65}.menu-list{display:grid;gap:8px;margin:0;padding:0;list-style:none}.menu-item{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;padding:15px 16px;border:1px solid #e4ece6;border-radius:9px;background:#fbfdfb}.menu-item.parent{background:#f7faf8}.menu-item.child{margin-left:24px;border-left:3px solid #b8d7c5}.menu-summary{min-width:0}.menu-summary strong,.menu-summary small{display:block}.menu-summary strong{color:#214838;font-size:15px}.menu-summary small{margin-top:4px;color:#74857c;font-size:12px;line-height:1.45}.status,.expand-button{padding:4px 8px;border-radius:999px;color:#28614c;background:#e5f4e9;font-size:12px}.status.disabled{color:#7a5e38;background:#f7eddc}.expand-button{border:0;border-radius:7px;color:#28614c;cursor:pointer}.text-button,.primary,.ghost,.icon-button{font:inherit;cursor:pointer}.text-button{border:0;color:#1b6854;background:none;font-weight:700}.primary{min-height:40px;padding:0 14px;border:0;border-radius:8px;color:#fff;background:#1e6956;font-weight:700}.ghost{min-height:40px;padding:0 14px;border:1px solid #bfd4c7;border-radius:8px;color:#176851;background:#fff;font-weight:700}.muted{padding:42px 0;color:#7a8981;text-align:center}.modal-backdrop{position:fixed;z-index:60;inset:0;display:grid;place-items:center;padding:20px;background:rgba(14,28,22,.46)}.modal-card{display:flex;width:min(680px,100%);max-height:calc(100vh - 40px);flex-direction:column;overflow:hidden;border-radius:16px;background:#fff;box-shadow:0 24px 72px rgba(0,0,0,.22)}.modal-heading{flex:0 0 auto;padding:26px 32px 0}.modal-scroll{min-height:0;overflow-y:auto;padding:18px 32px 28px;scrollbar-gutter:stable}.modal-scroll .helper{margin-bottom:18px}.icon-button{display:grid;width:32px;height:32px;place-items:center;border:0;border-radius:7px;color:#52645a;background:#eff3f0;font-size:23px;line-height:1}.form-stack{display:grid;gap:15px;margin-top:0}.form-stack label{display:grid;gap:7px;color:#4d6258;font-size:13px;font-weight:650}.form-stack input,.form-stack select{width:100%;min-height:44px;padding:0 12px;border:1px solid #cfdcd3;border-radius:8px;color:#192820;background:#fff}.form-stack .switch{display:flex;align-items:center;gap:8px}.form-stack .switch input{width:16px;height:16px;accent-color:#1e6956}.modal-actions{position:sticky;bottom:0;justify-content:flex-end;padding:16px 0 2px;background:#fff;box-shadow:0 -10px 16px rgba(255,255,255,.92)}@media(max-width:700px){.panel{padding:20px}.heading-actions{flex-wrap:wrap;justify-content:flex-end}.menu-item{flex-direction:column}.actions{width:100%;justify-content:flex-end}.menu-item.child{margin-left:10px}.modal-heading{padding:24px 22px 0}.modal-scroll{padding:16px 22px 24px}}
</style>
